def post(payload):
    headers = {"Authorization": f"Bearer {tok}", "Host": "docker-host:8765",
               "Origin": "http://docker-host:8765", "Content-Type": "application/json",
               "Accept": "application/json, text/event-stream",
               "MCP-Protocol-Version": PROTO}
    r = urllib.request.Request(URL, data=json.dumps(payload).encode(), method="POST", headers=headers)
    resp = urllib.request.urlopen(r, timeout=15)
    text = resp.read().decode()
    if not text.strip():
        return {}
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        data = [l[6:] for l in text.splitlines() if l.startswith("data: ")]
        return json.loads(data[-1])

post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{
    "protocolVersion":PROTO,"capabilities":{},"clientInfo":{"name":"verify","version":"0"}}})
post({"jsonrpc":"2.0","method":"notifications/initialized"})

tools = post({"jsonrpc":"2.0","id":2,"method":"tools/list"})
names = [t["name"] for t in tools["result"]["tools"]]
print(f"tools/list: {len(names)} tools -> {', '.join(names)}")

